/**
 * The portals of one level (ADR 0077 D5): one {@link Entry} per lit or built portal, the inside rectangle and the portal
 * block's id. Immutable; {@link PortalIndexAttachment} stores it as the persistent {@code ServerLevel} attachment
 * {@code <mod id>:portals}. Entries are kept sorted by block, then position, so the saved form is stable.
 */
public record PortalIndex(List<Entry> entries) {
    // Before EMPTY: the constructor sorts with it.
    private static final Comparator<Entry> ORDER = Comparator.comparing((Entry e) -> e.block().toString())
            .thenComparingInt(e -> e.min().getX()).thenComparingInt(e -> e.min().getY()).thenComparingInt(e -> e.min().getZ())
            .thenComparing(e -> e.axis().getSerializedName());

    /** No portals; the attachment is removed rather than saved empty. */
    public static final PortalIndex EMPTY = new PortalIndex(List.of());

    /** One portal: {@code min} is the lowest inside block ({@link PortalFrame.Rectangle#min()}). */
    public record Entry(Identifier block, BlockPos min, Direction.Axis axis, int width, int height) {
        /** The saved form {@code { block, min, axis, width, height }} (other keys are ignored; the runtime rejects them). */
        public static final Codec<Entry> CODEC = RecordCodecBuilder.create(i -> i.group(
                Identifier.CODEC.fieldOf("block").forGetter(Entry::block),
                BlockPos.CODEC.fieldOf("min").forGetter(Entry::min),
                Direction.Axis.CODEC.validate(a -> a == Direction.Axis.Y
                        ? DataResult.error(() -> "a portal axis is x or z")
                        : DataResult.success(a)).fieldOf("axis").forGetter(Entry::axis),
                Codec.intRange(PortalFrame.MIN_WIDTH, PortalFrame.MAX_WIDTH).fieldOf("width").forGetter(Entry::width),
                Codec.intRange(PortalFrame.MIN_HEIGHT, PortalFrame.MAX_HEIGHT).fieldOf("height").forGetter(Entry::height))
                .apply(i, Entry::new));

        public Entry {
            min = min.immutable();
        }

        /** The entry for a portal of {@code block} filling {@code rectangle}. */
        public static Entry of(Identifier block, PortalFrame.Rectangle rectangle) {
            return new Entry(block, rectangle.min(), rectangle.axis(), rectangle.width(), rectangle.height());
        }

        /** The inside rectangle. */
        public PortalFrame.Rectangle rectangle() {
            return new PortalFrame.Rectangle(min, axis, width, height);
        }

        /**
         * The inside block closest to {@code target}: {@code target} clamped to the rectangle on each coordinate. Used for
         * the search radius and the distance, so a wide portal counts from its nearest block.
         */
        public BlockPos closestTo(BlockPos target) {
            BlockPos max = rectangle().max();
            return new BlockPos(clamp(target.getX(), min.getX(), max.getX()), clamp(target.getY(), min.getY(), max.getY()),
                    clamp(target.getZ(), min.getZ(), max.getZ()));
        }

        private static int clamp(int value, int low, int high) {
            return Math.max(low, Math.min(high, value));
        }
    }

    /** The saved form: a list of entries. */
    public static final Codec<PortalIndex> CODEC = Entry.CODEC.listOf().xmap(PortalIndex::new, PortalIndex::entries);

    public PortalIndex {
        entries = entries.stream().sorted(ORDER).toList();
    }

    public boolean isEmpty() {
        return entries.isEmpty();
    }

    /**
     * This index with {@code entry}; an entry of the same block whose rectangle shares a block with it is replaced (a
     * portal relit in a resized frame, or indexed twice).
     */
    public PortalIndex with(Entry entry) {
        List<Entry> out = new ArrayList<>();
        for (Entry e : entries) {
            if (!(e.block().equals(entry.block()) && overlaps(e, entry))) {
                out.add(e);
            }
        }
        out.add(entry);
        return new PortalIndex(out);
    }

    /** This index without {@code entry} (equal entries only). */
    public PortalIndex without(Entry entry) {
        return new PortalIndex(entries.stream().filter(e -> !e.equals(entry)).toList());
    }

    /** The entry of {@code block} whose inside holds {@code pos}, if any. */
    public Optional<Entry> at(Identifier block, BlockPos pos) {
        return entries.stream().filter(e -> e.block().equals(block) && e.rectangle().contains(pos)).findFirst();
    }

    /**
     * The entries of {@code block} within the square {@code radius} of {@code target} (x and z of the closest inside
     * block at most {@code radius} away; any height), whose closest block passes {@code inBounds} (the world border),
     * closest first by squared distance, then lowest y, then the saved order.
     */
    public List<Entry> candidates(Identifier block, BlockPos target, int radius, Predicate<BlockPos> inBounds) {
        record Scored(Entry entry, BlockPos closest, long distance) {}
        List<Scored> scored = new ArrayList<>();
        for (Entry e : entries) {
            if (!e.block().equals(block)) {
                continue;
            }
            BlockPos closest = e.closestTo(target);
            if (Math.abs(closest.getX() - target.getX()) > radius || Math.abs(closest.getZ() - target.getZ()) > radius
                    || !inBounds.test(closest)) {
                continue;
            }
            scored.add(new Scored(e, closest, (long) Math.round(closest.distSqr(target))));
        }
        scored.sort(Comparator.comparingLong(Scored::distance).thenComparingInt(s -> s.entry().min().getY()));
        return scored.stream().map(Scored::entry).toList();
    }

    private static boolean overlaps(Entry a, Entry b) {
        BlockPos aMax = a.rectangle().max();
        BlockPos bMax = b.rectangle().max();
        return a.min().getX() <= bMax.getX() && b.min().getX() <= aMax.getX() && a.min().getY() <= bMax.getY()
                && b.min().getY() <= aMax.getY() && a.min().getZ() <= bMax.getZ() && b.min().getZ() <= aMax.getZ();
    }
}
